const call = async (opts) => {
  let lastErr;
  for (let i = 1; i <= 3; i++) {
    try { return await this.helpers.httpRequest({ json: true, timeout: 120000, ...opts }); }
    catch (e) { lastErr = e; if (i < 3) await new Promise((r) => setTimeout(r, 800 * i)); }
  }
  throw lastErr;
};
